// The Notes tab: my open private notes on this package, this page first (docs/07-author-notes.qmd).
import { useEffect, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import * as api from '../api.ts'
import type { MarkRow } from '../../../shared/types.ts'
import { whereText } from './PageMarks.tsx'
import { Md } from './Md.tsx'
import { buildPacket } from '../features/packet.ts'

export function Notes({ s }: { s: State }) {
  const [all, setAll] = useState<MarkRow[] | null>(null)
  const [showDone, setShowDone] = useState(false)
  const [q, setQ] = useState('')
  const [err, setErr] = useState<string | null>(null)
  const reload = () => {
    if (!s.pkg) return
    api.myNotes(s.pkg.id).then(setAll).catch((e) => setErr(String(e)))
  }
  useEffect(reload, [s.pkg?.id, s.marks.length])
  if (!s.pkg) return null
  if (err) return <div class="err">{err}</div>
  if (!all) return <div class="muted pad">Loading…</div>
  const page = s.hello?.page
  const order = s.build?.toc?.pages?.map((p) => p.page) || []
  const rank = (m: MarkRow) => (m.page === page ? -1 : order.indexOf(m.page || ''))
  const list = all
    .filter((m) => showDone || m.status !== 'done')
    .filter((m) => !q || (m.body || '').toLowerCase().includes(q.toLowerCase()) || whereText(m).toLowerCase().includes(q.toLowerCase()))
    .sort((a, b) => rank(a) - rank(b) || a.created_at.localeCompare(b.created_at))
  const exportPacket = async () => {
    try {
      const build = await api.latestBuild(s.pkg!.id, true)
      const notes = all.filter((m) => m.status !== 'done' && !(m.kind === 'suggestion' && !m.body))
      const md = buildPacket(s.pkg!, build, notes)
      const stamp = new Date().toISOString().slice(0, 16).replace('T', '-').replace(':', '')
      const name = `${s.pkg!.slug.split('/')[1]}-notes-${stamp}.md`
      const blob = new Blob([md], { type: 'text/markdown' })
      const a = document.createElement('a')
      a.href = URL.createObjectURL(blob)
      a.download = name
      a.click()
      await Promise.all(notes.filter((m) => m.status === 'open').map((m) => api.updateMark(m.id, { status: 'exported' })))
      reload()
    } catch (e) {
      setErr(String(e))
    }
  }
  return (
    <div class="notes">
      <div class="row">
        <input type="search" placeholder="Search notes" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} />
        <label class="chk"><input type="checkbox" checked={showDone} onChange={(e) => setShowDone((e.target as HTMLInputElement).checked)} /> Show done</label>
      </div>
      <div class="row">
        <button class="small" onClick={exportPacket} disabled={!all.length}>Export packet (.md)</button>
        <span class="muted small">{all.filter((m) => m.status !== 'done').length} open</span>
      </div>
      {list.map((m) => (
        <div key={m.id} class={`mark ${m.kind === 'suggestion' ? 'k-suggestion' : 'k-author_note'} ${m.status}`}>
          <div class="mark-head">
            <span class="kind">{m.data.category as string} · p{m.data.priority as number}{m.status !== 'open' ? ` · ${m.status}` : ''}</span>
            <span class="muted small">{m.page === page ? 'this page' : titleOf(s, m.page)}</span>
          </div>
          {m.page === page ? <button class="link where" onClick={() => store.goto(m.id)}>{whereText(m)}</button> : (
            <a class="where" href={pageUrl(s, m)} target="_top">{whereText(m)}</a>
          )}
          {m.body && <div class="body-md"><Md text={m.body} /></div>}
          <div class="actions">
            {m.page === page && <button class="small" onClick={() => store.edit(m)}>Edit</button>}
            {m.status !== 'done' ? <button class="small" onClick={() => store.setStatus(m, 'done')}>Done</button> : <button class="small" onClick={() => store.setStatus(m, 'open')}>Reopen</button>}
            <button class="small danger" onClick={() => { if (confirm('Delete this note?')) store.remove(m.id).then(reload) }}>Delete</button>
          </div>
        </div>
      ))}
      {!list.length && <div class="muted pad">No notes{q ? ' match' : ''}.</div>}
    </div>
  )
}

function titleOf(s: State, page: string | null): string {
  const p = s.build?.toc?.pages?.find((x) => x.page === page)
  return p?.title || page || 'whole book'
}
function pageUrl(s: State, m: MarkRow): string {
  const p = s.build?.toc?.pages?.find((x) => x.page === m.page)
  const site = s.pkg?.site_url || ''
  return p ? `${site}${p.path}#yrS4=${m.id}` : '#'
}
