// The note and comment editors: the only place in the overlay where text is typed (docs/07-author-notes.qmd).
import { useEffect, useRef, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import { LabelPicker } from './Labels.tsx'
import { Md } from './Md.tsx'
import { useState as useSt } from 'preact/hooks'

const CATEGORIES = ['fix', 'move', 'insert', 'rewrite', 'check-facts', 'typo', 'style', 'idea', 'other']
const TOPICS: Array<[string, string]> = [['question', 'A question'], ['confused', "I'm confused"], ['error-in-book', 'Error in the book'], ['other', 'Other']]

export function Editor({ s }: { s: State }) {
  const p = s.pending!
  if (p.kind === 'label') return <LabelEditorPending s={s} />
  const draftKey = `yrS4-draft-${s.pkg?.id}-${p.editing?.id || 'new'}-${p.kind}`
  const isEdit = p.kind === 'suggestion'
  const [body, setBody] = useState<string>(() => p.editing?.body || safeGet(draftKey) || (isEdit ? String(p.data?.original_md || '') : ''))
  const [preview, setPreview] = useState(false)
  const [category, setCategory] = useState<string>((p.editing?.data.category as string) || 'fix')
  const [priority, setPriority] = useState<number>(Number(p.editing?.data.priority) || 2)
  const [proposed, setProposed] = useState<string>((p.editing?.data.proposed as string) || '')
  const [showProposed, setShowProposed] = useState(!!p.editing?.data.proposed)
  const [topic, setTopic] = useState<string>((p.editing?.data.topic as string) || 'question')
  const ta = useRef<HTMLTextAreaElement>(null)
  useEffect(() => { ta.current?.focus() }, [])
  useEffect(() => { safeSet(draftKey, body) }, [body])

  const isNote = p.kind === 'author_note'
  const isMessage = p.kind === 'message'
  const isStudentNote = p.kind === 'student_note'
  const isCoverage = p.kind === 'coverage'
  const where = p.anchor.scope === 'page' ? 'whole page' : p.anchor.scope === 'section' ? `section: ${p.anchor.section?.headings.slice(-1)[0]}` : p.quoteText || ''
  const save = async () => {
    if (isCoverage) {
      await store.saveCoverage(p.anchor, p.status || 'covered')
      return
    }
    if (!body.trim() && !isNote) return
    const data = isNote ? { category, priority, ...(proposed.trim() ? { proposed } : {}) } : isMessage ? { topic } : {}
    await store.saveText(p, body, data)
    safeSet(draftKey, '')
  }
  const onKey = (e: KeyboardEvent) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); save() }
    if (e.key === 'Escape') { e.preventDefault(); store.cancelPending() }
  }
  const title = isEdit ? (p.editing ? 'Edit my edit' : 'Edit this text') : isCoverage ? 'Save coverage' : p.kind === 'comment' ? 'Comment for students' : isMessage ? 'Ask my instructor' : isStudentNote ? 'My note' : 'Private note'
  return (
    <div class="editor" onKeyDown={onKey}>
      <div class="editor-head"><strong>{title}</strong> <span class="muted small">{p.anchor.section?.headings.join(' › ')}</span></div>
      {!isEdit && <div class="quote">{where}</div>}
      {isEdit && (
        <div class="muted small">The block's Markdown, reconstructed from the page (the book's source may differ in details). Your version replaces the block on your screen only; the source is changed later, when the proposals are applied (Notes → Export).</div>
      )}
      {isCoverage && (
        <>
          <div class="warn small">Tick the sections this counts for (Teach bar above), then save.</div>
        </>
      )}
      {isNote && (
        <div class="row">
          <select value={category} onChange={(e) => setCategory((e.target as HTMLSelectElement).value)}>
            {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
          <span class="lbl">Priority</span>
          {[1, 2, 3].map((n) => (
            <label key={n} class="chk"><input type="radio" name="prio" checked={priority === n} onChange={() => setPriority(n)} /> {n}</label>
          ))}
        </div>
      )}
      {isMessage && (
        <div class="row">
          <select value={topic} onChange={(e) => setTopic((e.target as HTMLSelectElement).value)}>
            {TOPICS.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
          <span class="muted small">Only you and your section's staff see this.</span>
        </div>
      )}
      {isEdit && preview && <div class="md edit-preview"><Md text={body} /></div>}
      {!isCoverage && (
        <textarea ref={ta} rows={isEdit ? 10 : 4} style={isEdit && preview ? { display: 'none' } : undefined} value={body} placeholder={isNote ? 'What should change here?' : isMessage ? 'Your question or comment about this passage' : isStudentNote ? 'Your note (only you see it)' : 'What students should know about this passage (Markdown)'} onInput={(e) => setBody((e.target as HTMLTextAreaElement).value)} />
      )}
      {isNote && (
        <div>
          <button class="link small" onClick={() => setShowProposed(!showProposed)}>{showProposed ? '▾' : '▸'} Proposed text (optional)</button>
          {showProposed && <textarea rows={4} value={proposed} placeholder="Replacement wording, Markdown" onInput={(e) => setProposed((e.target as HTMLTextAreaElement).value)} />}
        </div>
      )}
      <div class="actions">
        <button class="primary" disabled={s.busy || (!isCoverage && !isNote && !body.trim()) || (isCoverage && !s.teachSections.length)} onClick={save}>Save <span class="kbd">Ctrl+Enter</span></button>
        {isEdit && <button onClick={() => setPreview(!preview)}>{preview ? 'Edit' : 'Preview'}</button>}
        {isEdit && !p.editing && <button onClick={() => setBody(String(p.data?.original_md || ''))} title="Back to the block's own text">Reset</button>}
        <button onClick={() => store.cancelPending()}>Cancel <span class="kbd">Esc</span></button>
      </div>
    </div>
  )
}

function safeGet(k: string): string {
  try { return localStorage.getItem(k) || '' } catch { return '' }
}
function safeSet(k: string, v: string) {
  try { v ? localStorage.setItem(k, v) : localStorage.removeItem(k) } catch { /* ignore */ }
}

function LabelEditorPending({ s }: { s: State }) {
  const p = s.pending!
  const [sel, setSel] = useSt<string[]>(s.currentLabel ? [s.currentLabel] : [])
  const where = p.anchor.scope === 'page' ? 'whole page' : p.anchor.scope === 'section' ? `section: ${p.anchor.section?.headings.slice(-1)[0]}` : p.quoteText || ''
  return (
    <div class="editor">
      <div class="editor-head"><strong>Label this passage</strong> <span class="muted small">{p.anchor.section?.headings.join(' › ')}</span></div>
      <div class="quote">{where}</div>
      <LabelPicker s={s} selected={sel} onChange={setSel} onDone={() => store.saveLabelMark(p.anchor, sel, p.quoteText)} />
    </div>
  )
}
